local function _bxor(a, b)
    local r, bit = 0, 1
    while a > 0 or b > 0 do
        local aa = a % 2
        local bb = b % 2
        if aa ~= bb then r = r + bit end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        bit = bit * 2
    end
    return r
end

local _alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _map = {}
for i = 1, #_alpha do
    _map[string.byte(_alpha, i)] = i - 1
end

local function _decode_b64(t)
    local out = {}
    local oi = 1
    for n = 1, #t do
        local s = t[n]
        local i = 1
        while i <= #s do
            local c1 = string.byte(s, i); i = i + 1
            local c2 = string.byte(s, i); i = i + 1
            local c3 = string.byte(s, i); i = i + 1
            local c4 = string.byte(s, i); i = i + 1
            if not c1 or not c2 then break end
            local a = _map[c1] or 0
            local b = _map[c2] or 0
            local c = (c3 and c3 ~= 61) and (_map[c3] or 0) or 0
            local d = (c4 and c4 ~= 61) and (_map[c4] or 0) or 0
            out[oi] = string.char(a * 4 + math.floor(b / 16)); oi = oi + 1
            if c3 and c3 ~= 61 then
                out[oi] = string.char((b % 16) * 16 + math.floor(c / 4)); oi = oi + 1
            end
            if c4 and c4 ~= 61 then
                out[oi] = string.char((c % 4) * 64 + d); oi = oi + 1
            end
        end
    end
    return table.concat(out)
end

local _raw = _decode_b64(_B64)
_B64 = nil
_map = nil
_alpha = nil

local _out = {}
for i = 1, #_raw do
    local v = string.byte(_raw, i)
    local k2 = (167 + i * 19 + (i % 251) * 7) % 256
    local x = (v - k2) % 256
    local k1 = (109 + i * 37 + math.floor(i / 256) * 11) % 256
    _out[i] = string.char(_bxor(x, k1))
end
_raw = nil

local _source = table.concat(_out)
_out = nil

local _fn, _err = loadstring(_source)
_source = nil
if not _fn then error(_err) end
return _fn()
